        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float32, "Kernel specialized for float32 tensors."
        x = x.contiguous()

        dim = self.dim
        if dim < 0:
            dim = dim + x.dim()

        shape = list(x.shape)

