            "max_reduce_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                output,
                i32(outer_size),
                i32(reduce_size),
                i32(inner_size),
                i32(total_size),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
